native.captureDefersStdout:
Term io_feature_capture_run(Env e, Term *f, IoWork *w) {
  feature_require(interval_ready && feature_active);
  uint64_t length = 0;
  char *text = io_cstr(e, f[0], &length);
  FeatureChunk *chunk = malloc(sizeof(FeatureChunk)); feature_require(chunk != NULL);
  chunk->text = text; chunk->length = length; chunk->next = NULL;
  for (uint64_t i = 0; i < length; ++i) feature_digest = (feature_digest ^ (uint8_t)text[i]) * UINT32_C(16777619);
  feature_digest = (feature_digest ^ UINT32_C(10)) * UINT32_C(16777619);
  feature_bytes += length + 1;
  if (feature_tail) feature_tail->next = chunk; else feature_head = chunk;
  feature_tail = chunk;
  return term_pak(CID_UNIT, 0);
}

native.endClosesInterval:
Term io_feature_end_run(Env e, Term *f, IoWork *w) {
  feature_require(feature_active);
  struct timespec stop; feature_require(clock_gettime(CLOCK_MONOTONIC, &stop) == 0);
  int64_t elapsed = ((int64_t)stop.tv_sec - feature_start.tv_sec) * INT64_C(1000000000) + stop.tv_nsec - feature_start.tv_nsec;
  feature_require(elapsed >= 0); feature_active = false;
  interval_elapsed += elapsed; interval_count++; return term_pak(CID_UNIT,0);
}

native.finishChecksThenEmits:
Term io_interval_finish_run(Env e, Term *f, IoWork *w) {
  feature_require(interval_ready && !feature_active && interval_count == (uint32_t)f[0]);
  fprintf(stderr, "{\"elapsedNs\":\"%" PRIi64 "\",\"bytes\":%" PRIu64 ",\"digest\":%" PRIu32 ",\"intervals\":%" PRIu32 "}\n", interval_elapsed, feature_bytes, feature_digest, interval_count);
  while (feature_head) {
    FeatureChunk *chunk = feature_head; feature_head = chunk->next;
    io_out(stdout, chunk->text, chunk->length); io_out(stdout, "\n", 1);
    free(chunk->text); free(chunk);
  }
  feature_tail = NULL; interval_ready=false;
  return term_pak(CID_UNIT, 0);
}

native.strictIoRequestBeforeForeignDispatch:
static void io_step(Env e, IoWork* a) {
  for (;;) {
    u64  ap  = task_node(e, FID_CLO_APPLY, TERM_HOLE, 0, 0);
    e.mem[ap]     = a->cont;
    e.mem[ap + 1] = a->item;
    Term req = corpus_eval(e.mem, term_tsk(FID_CLO_APPLY, ap));
    u32  c   = (u32)term_aux(req);
    u64  at  = term_peek(e.mem, req);
    if (c == CID_EMIT) {
      term_drop(e, req);
      free(a);
      io_live -= 1;
      return;
    }
    if (c == CID_HALT) {
      io_errs(e, e.mem[at + 1]);
      exit((int)(u32)e.mem[at]);
    }
    if (io_eff_rows[c].run == NULL) {
      err_fail("an alien request");
    }
    u32 need = io_eff_rows[c].ask;
    u32 word = (u32)(need & IO_READ ? io_hand_v(e.mem[at]) : e.mem[at]);
    a->cont  = req;
    if (need != 0) {
      io_wait_on(a, (int)word, need & IO_READ ? POLLIN : 0,
        need & IO_TIME ? io_tick() + (u64)word * 1000000ull : 0, io_exec);
      return;
    }
    Term x = io_exec(e, a);
    if (x == IO_PARK) {
      return;
    }
    a->item = x;
  }
}

